@namespace sv_1874c09d68634becac32c57c81fcb7da.Components.Pages.Settings

<nav class="settings-sidebar">
    <h2 class="sidebar-title">Settings</h2>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    min-height: 100vh;
}

.sidebar-title {
    font-size: 1.25rem;
    font-weight: 600;
    padding: 0 1.25rem;
    margin-bottom: 1.5rem;
    color: #1a1a1a;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    color: #555;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.sidebar-item:hover {
    background: #e9ecef;
    color: #1a1a1a;
}

.sidebar-item.active {
    background: #e3f2fd;
    color: #1565c0;
    border-left-color: #1565c0;
    font-weight: 500;
}

.sidebar-icon {
    font-size: 1.1rem;
}

.sidebar-label {
    font-size: 0.95rem;
}

@namespace sv_1874c09d68634becac32c57c81fcb7da.Components.Pages.Settings
@using sv_1874c09d68634becac32c57c81fcb7da.Services

<div class="profile-section">
    <h3>Profile Settings</h3>

    @if (_successMessage is not null)
    {
        <div class="toast-success">@_successMessage</div>
    }

    <div class="avatar-preview">
        <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
        <p class="avatar-url">@_avatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="_displayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="_email" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="_bio" class="form-control" rows="4"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private string? _successMessage;

    protected override void OnParametersSet()
    {
        ResetFromProfile();
    }

    private void ResetFromProfile()
    {
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _avatarUrl = Profile.AvatarUrl;
        _bio = Profile.Bio;
        _successMessage = null;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);

        _successMessage = "Profile saved successfully!";
        _saving = false;

        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        ResetFromProfile();
    }
}

.profile-section {
    max-width: 600px;
}

.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

.avatar-url {
    font-size: 0.85rem;
    color: #666;
    word-break: break-all;
    margin: 0;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #1565c0;
    box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.15);
}

textarea.form-control {
    resize: vertical;
}

.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-primary {
    background: #1565c0;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.toast-success {
    background: #c8e6c9;
    color: #2e7d32;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1.25rem;
    font-weight: 500;
}

