@namespace sv_1874c09d68634becac32c57c81fcb7da.Components.Pages.Settings
@using sv_1874c09d68634becac32c57c81fcb7da.Services

<div class="notifications-section">
    <h3>Notification Preferences</h3>

    <div class="toggle-group">
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" checked="@_emailNotifications"
                       @onchange="e => _emailNotifications = (bool)e.Value!" />
                <span class="toggle-text">Email Notifications</span>
            </label>
            <p class="toggle-desc">Receive notifications via email</p>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" checked="@_pushNotifications"
                       @onchange="e => _pushNotifications = (bool)e.Value!" />
                <span class="toggle-text">Push Notifications</span>
            </label>
            <p class="toggle-desc">Receive browser push notifications</p>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" checked="@_weeklyDigest"
                       @onchange="e => _weeklyDigest = (bool)e.Value!" />
                <span class="toggle-text">Weekly Digest</span>
            </label>
            <p class="toggle-desc">Get a weekly summary of activity</p>
        </div>
    </div>

    <h4>Muted Channels</h4>
    <div class="channel-list">
        @foreach (var channel in _allChannels)
        {
            <label class="channel-item">
                <input type="checkbox" checked="@_mutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>
    </div>

    @if (_saved)
    {
        <div class="toast-success">Preferences saved!</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = [];
    private bool _saving;
    private bool _saved;

    private static readonly string[] _allChannels = ["announcements", "marketing", "social", "product-updates", "engineering"];

    protected override void OnParametersSet()
    {
        _emailNotifications = Prefs.EmailNotifications;
        _pushNotifications = Prefs.PushNotifications;
        _weeklyDigest = Prefs.WeeklyDigest;
        _mutedChannels = [.. Prefs.MutedChannels];
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _saved = false;

        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await OnSave.InvokeAsync(updated);

        _saved = true;
        _saving = false;

        _ = DismissAfterDelay();
    }

    private async Task DismissAfterDelay()
    {
        await Task.Delay(3000);
        _saved = false;
        await InvokeAsync(StateHasChanged);
    }
}

.notifications-section {
    max-width: 600px;
}

.toggle-group {
    margin-bottom: 2rem;
}

.toggle-item {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-text {
    font-weight: 500;
    color: #333;
}

.toggle-desc {
    margin: 0.25rem 0 0 1.75rem;
    font-size: 0.85rem;
    color: #666;
}

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.4rem 0.5rem;
    border-radius: 4px;
}

.channel-item:hover {
    background: #f5f5f5;
}

.button-group {
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
}

.btn-primary {
    background: #1565c0;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast-success {
    background: #c8e6c9;
    color: #2e7d32;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-weight: 500;
}

