@namespace sv_1874c09d68634becac32c57c81fcb7da.Components.Pages.Settings
@using sv_1874c09d68634becac32c57c81fcb7da.Services

<div class="security-section">
    <h3>Security Settings</h3>

    <!-- Change Password Panel -->
    <div class="panel">
        <div class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>🔑 Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▾" : "▸")</span>
        </div>
        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPw">Current Password</label>
                    <input id="currentPw" type="password" @bind="_currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPw">New Password</label>
                    <input id="newPw" type="password" @bind="_newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPw">Confirm Password</label>
                    <input id="confirmPw" type="password" @bind="_confirmPassword" class="form-control" />
                </div>

                @if (_passwordError is not null)
                {
                    <div class="error-message">@_passwordError</div>
                }
                @if (_passwordSuccess)
                {
                    <div class="toast-success">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@_updatingPassword">
                    @(_updatingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="panel">
        <div class="panel-body tfa-panel">
            <div class="tfa-info">
                <span class="tfa-label">Two-Factor Authentication</span>
                <span class="status-badge @(Security.TwoFactorEnabled ? "status-on" : "status-off")">
                    @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (Security.LastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="panel">
        <div class="panel-header">
            <span>📱 Active Sessions</span>
        </div>
        <div class="panel-body">
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != _currentSessionId)
                                {
                                    <button class="btn btn-sm btn-danger" @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>

    @if (_sessionToRevoke is not null)
    {
        <RevokeSessionDialog
            Title="Revoke Session"
            Message="@($"Are you sure you want to revoke the session on \"{_sessionToRevoke.Device}\" in {_sessionToRevoke.Location}? This will sign out that device.")"
            ConfirmText="Revoke Session"
            OnConfirm="ConfirmRevokeAsync"
            OnCancel="CancelRevoke" />
    }
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _passwordSuccess;
    private bool _updatingPassword;
    private ActiveSession? _sessionToRevoke;

    // First session is treated as current
    private string _currentSessionId => Security.Sessions.FirstOrDefault()?.Id ?? "";

    private async Task UpdatePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _updatingPassword = true;
        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _updatingPassword = false;

        _passwordSuccess = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

