+    <div class="setting-group">
+        <label class="toggle-label">
+            <input type="checkbox" checked="@_compactMode"
+                   @onchange="e => _compactMode = (bool)e.Value!" />
+            <span>Compact Mode</span>
+        </label>
+        <p class="setting-desc">Reduce spacing and padding throughout the interface</p>
+    </div>
+
+    <!-- Live Preview -->
+    <div class="preview-area @GetPreviewClass()">
+        <div class="preview-header">Live Preview</div>
+        <div class="preview-content">
+            <p class="preview-text">This is how your content will look with the selected settings.</p>
+            <div class="preview-card">
+                <strong>Sample Card</strong>
+                <p>A preview of the appearance with your chosen theme, font size, and spacing.</p>
+            </div>
+        </div>
+    </div>
+
+    <div class="button-group">
+        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
+            @(_saving ? "Saving..." : "Save")
+        </button>
+    </div>
+
+    @if (_saved)
+    {
+        <div class="toast-success">Appearance settings saved!</div>
+    }
+</div>
+
+@code {
+    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
+    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }
+
+    private string _theme = "System";
+    private string _fontSize = "Medium";
+    private string _language = "English";
+    private bool _compactMode;
+    private bool _saving;
+    private bool _saved;
+
+    private static readonly string[] _themes = ["Light", "Dark", "System"];
+    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
+    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];
+
+    protected override void OnParametersSet()
+    {
+        _theme = Settings.Theme;
+        _fontSize = Settings.FontSize;
+        _language = Settings.Language;
+        _compactMode = Settings.CompactMode;
+    }
+
+    private string GetPreviewClass()
+    {
+        var classes = new List<string>();
+
+        classes.Add(_theme.ToLowerInvariant() switch
+        {
+            "dark" => "preview-dark",
+            "light" => "preview-light",
+            _ => "preview-system"
+        });
+
+        classes.Add(_fontSize.ToLowerInvariant() switch
+        {
+            "small" => "preview-font-small",
+            "large" => "preview-font-large",
+            _ => "preview-font-medium"
+        });
+
+        if (_compactMode) classes.Add("preview-compact");
+
+        return string.Join(" ", classes);
+    }
+
+    private async Task SaveAsync()
+    {
+        _saving = true;
+        _saved = false;
+
+        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await OnSave.InvokeAsync(updated);
+
+        _saved = true;
+        _saving = false;
+
+        _ = DismissAfterDelay();
+    }
+
+    private async Task DismissAfterDelay()
+    {
+        await Task.Delay(3000);
+        _saved = false;
+        await InvokeAsync(StateHasChanged);
+    }
+}
+

toolArgs.file_text:
.appearance-section {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.group-label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.5rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.form-control {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
}

.select-control {
    width: 200px;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-weight: 500;
}

.setting-desc {
    margin: 0.25rem 0 0 1.5rem;
    font-size: 0.85rem;
    color: #666;
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 1.5rem;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.6rem 1rem;
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    border-bottom: 1px solid #e0e0e0;
}

.preview-content {
    padding: 1.25rem;
}

.preview-card {
    border: 1px solid currentColor;
    border-radius: 6px;
    padding: 0.75rem;
    margin-top: 0.75rem;
    opacity: 0.8;
}

.preview-card p {
    margin: 0.3rem 0 0;
}

/* Theme variants */
.preview-light {
    background: #ffffff;
    color: #1a1a1a;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
}

.preview-dark .preview-header {
    background: #2a2a3e;
    border-color: #444;
}

.preview-dark .preview-card {
    border-color: #555;
}

.preview-system {
    background: #f5f5f5;
    color: #333;
}

.preview-system .preview-header {
    background: #e8e8e8;
}

/* Font size variants */
.preview-font-small .preview-content {
    font-size: 0.8rem;
}

.preview-font-medium .preview-content {
    font-size: 0.95rem;
}

.preview-font-large .preview-content {
    font-size: 1.15rem;
}

/* Compact mode */
.preview-compact .preview-content {
    padding: 0.6rem;
}

.preview-compact .preview-card {
    padding: 0.4rem;
    margin-top: 0.4rem;
}

.button-group {
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
}

.btn-primary {
    background: #1565c0;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast-success {
    background: #c8e6c9;
    color: #2e7d32;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-weight: 500;
}

